/*
 * A273465  Numbers generated by starting at 1 and adding twice and
 *          subtracting once following the sequence of positive integers.
 * https://oeis.org/A273465
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n*(n+1)/2 - t*(3*t+5), where t = (n-1)/3
 * Range:     u8 n <= 38, u16 n <= 626, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Returns the nth term of OEIS sequence A273465.  */
seq_t a(idx_t n)
{
    seq_t N = (seq_t)n;           /* convert index to seq_t */
    seq_t t = (N - 1) / 3;        /* number of indices ≡1 (mod 3) up to n */
    seq_t total = N * (N + 1) / 2;/* sum of 1…n */
    seq_t adjust = t * (3 * t + 5);/* 2 * sum of the “subtracted” numbers */
    return total - adjust;
}
